/**
 * Builds the station's machines from the catalog and places them in the station frame.
 * @param {object} o
 * @param {object} o.registry  the catalog (components, products, ops)
 * @param {object} o.ctx       build context: materials, belt height
 * @returns {{ root: THREE.Group, equipment: object }}
 */
export function build({ registry, ctx }) {
  const root = new THREE.Group();
  root.name = 'T1 Can Transfer';
  const equipment = {};

  // belt: Flat-belt conveyor for loose units (cans, bottles, cases): drums, return...
  equipment.belt = registry.buildComponent('beltConveyor', {
    length: 3,
    beltWidth: 0.52,
    guideGap: 0.46,
    drive: false,
    carries: 'batch',
  }, ctx);
  root.add(equipment.belt.root);

  // standaloneInfeed: Flat-belt conveyor for loose units (cans, bottles, cases): drums, return...
  equipment.standaloneInfeed = registry.buildComponent('beltConveyor', {
    length: 1.3,
    beltWidth: 0.34,
    guideGap: 0.2,
    drive: false,
    carries: 'batch',
  }, ctx);
  equipment.standaloneInfeed.root.position.set(-2.15, 0, 0);
  root.add(equipment.standaloneInfeed.root);

  // singleFile: Single-file guide rails over a belt conveyor, on posts on its side frames...
  equipment.singleFile = registry.buildComponent('guideRails', {
    length: 1.6,
    span: 0.58,
    gap: 0.2,
  }, ctx);
  equipment.singleFile.root.position.set(-0.7, 0.87, 0);
  root.add(equipment.singleFile.root);

  // pusherA: Pneumatic side pusher on a floor stand beside a conveyor: its plate pushes...
  equipment.pusherA = registry.buildComponent('sidePusher', { plateLength: 0.68 }, ctx);
  equipment.pusherA.root.position.set(0.55, 0, 0);
  root.add(equipment.pusherA.root);

  // pusherB: Pneumatic side pusher on a floor stand beside a conveyor: its plate pushes...
  equipment.pusherB = registry.buildComponent('sidePusher', { plateLength: 0.68 }, ctx);
  equipment.pusherB.root.position.set(0.55, 0, 0);
  equipment.pusherB.root.rotation.y = Math.PI;
  root.add(equipment.pusherB.root);

  // divider: Lane divider blade along the middle of a belt conveyor, hung from bridges on...
  equipment.divider = registry.buildComponent('laneDivider', { length: 0.6, span: 0.58 }, ctx);
  equipment.divider.root.position.set(1.25, 0.87, 0);
  root.add(equipment.divider.root);

  return { root, equipment };
}
